reference_solution:
def minEatingSpeed(piles, h):
    lo, hi = 1, max(piles)
    while lo < hi:
        mid = (lo + hi) // 2
        hours = sum((p + mid - 1) // mid for p in piles)
        if hours <= h:
            hi = mid
        else:
            lo = mid + 1
    return lo

brute_force_solution:
def minEatingSpeed(piles, h):
    k = 1
    while True:
        if sum((p + k - 1) // k for p in piles) <= h:
            return k
        k += 1

